def compute(vars):
    total = vars["v1"] + vars["v2"] + vars["v3"] + vars["v4"] + vars["v5"]
    return {
        "value": total,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "v3": vars["v3"],
            "v4": vars["v4"],
            "v5": vars["v5"],
            "total": total,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
